    if res.mutation and res.mutation ~= "Normal" then S.muts[res.mutation] = (S.muts[res.mutation] or 0) + 1 end
    local inc = tonumber(res.income) or 0
    if not S.best or inc > S.best.inc then S.best = { name = res.name, rarity = rar, mutation = res.mutation, inc = inc } end
    if M.rank(rar) >= 6 then notify(rar .. __T[" fish: "] .. tostring(res.name)) LOG("big", rar, res.mutation, inc) end
    if on("f_stopOn") and Toggles and Toggles.f_draw then
        local stopR = M.rank(rar) >= (M.order[val("f_stopAt", "Celestial")] or 8)
        local sm = Opt and Opt.f_stopMut and Opt.f_stopMut.Value
        local stopM = type(sm) == "table" and res.mutation and sm[res.mutation] == true
        if stopR or stopM then pcall(function() Toggles.f_draw:SetValue(false) end) notify(__T["Stopped: "] .. rar .. " " .. tostring(res.mutation)) end
    end
    task.spawn(F.cleanup)
    return true
end
