U.skip = {}
function U.decorNext()
    local Dc = D.Decor
    if not Dc then return nil end
    local spots = Dc.spotsAt(tonumber(M.a("TankLevel")) or 1)
    local placed = gcall(Dc.decode, M.a("DecorPlaced") or "") or {}
    local owned = {}
    for id in tostring(M.a("DecorOwned") or ""):gmatch("[^,]+") do owned[id] = true end
    local weakest, wb, inUse = nil, math.huge, {}
    for i = 1, spots do
        local id = placed[i]
        local it = id and id ~= "" and Dc.find(id)
        local b = it and it.boost or 0
        if id and id ~= "" then inUse[id] = true end
        if b < wb then weakest, wb = i, b end
    end
    if not weakest then return nil end
    for _, it in ipairs(Dc.ITEMS) do
        if owned[it.id] and not inUse[it.id] and it.boost > wb then return { kind = "place", id = it.id, spot = weakest, cost = 0 } end
    end
    for _, it in ipairs(Dc.ITEMS) do
        if not owned[it.id] and it.boost > wb then return { kind = "decor", id = it.id, spot = weakest, cost = it.price } end
    end
end
function U.cands()
    local out = {}
    local lp_ = tonumber(M.a("LuckPrice"))
    if (not lp_ or lp_ <= 0) and D.Rules and D.Rules.luckPrice then lp_ = tonumber(gcall(D.Rules.luckPrice, tonumber(M.a("LuckLevel")) or 0)) end
    if on("u_luck") and lp_ and lp_ > 0 and (tonumber(M.a("LuckLevel")) or 0) < 10 then out[#out + 1] = { kind = "luck", cost = lp_, w = 0.4 } end
    local tp = tonumber(M.a("UpgradePrice"))
    if on("u_tank") and tp and tp > 0 and (tonumber(M.a("TankLevel")) or 1) < 15 then out[#out + 1] = { kind = "tank", cost = tp, w = 1 } end
    if on("u_decor") then local d = U.decorNext() if d then d.w = 2.5 out[#out + 1] = d end end
    local mode = val("u_mode", "Best Value")
    for _, c in ipairs(out) do
        c.score = c.cost * (mode == "Cheapest First" and 1 or c.w)
        local kind = c.kind == "place" and "decor" or c.kind
        if mode == "Go For One" and kind ~= (({ Luck = "luck", Tank = "tank", Decor = "decor" })[val("u_target", "Luck")] or "luck") then c.score = c.score + 1e30 end
    end
    table.sort(out, function(a, b) return a.score < b.score end)
    return out
end
function U.buy(c)
    if c.kind == "luck" then local r = M.call("UpgradeLuck") return type(r) == "table" and r.ok end
    if c.kind == "tank" then local r = M.call("UpgradeTank") return type(r) == "table" and r.ok end
    if c.kind == "place" then local r = M.call("PlaceDecor", c.spot, c.id) return type(r) == "table" and r.ok end
    if c.kind == "decor" then
        local r = M.call("BuyDecor", c.id)
        if type(r) == "table" and r.ok then M.call("PlaceDecor", c.spot, c.id) return true end
    end
    return false
end
