            setText(UI.u1, string.format(__T["Luck lvl %s (next %s)\nTank lvl %s (next %s)\nBought %d · Decor %d"], tostring(M.a("LuckLevel") or 0), M.fmt(M.a("LuckPrice") or 0), tostring(M.a("TankLevel") or 1), M.fmt(M.a("UpgradePrice") or 0), S.upgrades, S.decor))
            setText(UI.r1, string.format(__T["Pearls %s · Potions used %d · Active %d"], tostring(M.a("Pearls") or 0), S.potions, RW.activePotions()))
